package com.axplatform.sheet;
import com.axplatform.common.Problem;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class DataReportTest {
 static Map<String,Object> table(){return SheetRules.normalize(Map.of("columns",List.of(Map.of("id","party","label","거래처","type","TEXT"),Map.of("id","month","label","월","type","TEXT"),Map.of("id","qty","label","수량","type","NUMBER"),Map.of("id","price","label","단가","type","NUMBER")),"rows",List.of(List.of("거래처1","1월","2","10"),List.of("거래처1","1월","3","20"),List.of("거래처1","2월","4","30"),List.of("거래처2","1월","9","40"))));}
 static Map<String,Object> config(){return new LinkedHashMap<>(Map.of("format","AX_DATA_VIEW_1","mode","TABLE","sheetId","sheet1","name","보기"));}
 @Test void andFiltersOnSameColumnRespectBothBoundsAndOriginalRowAddresses(){var c=config();c.put("filters",List.of(Map.of("column","qty","operator","GTE","value","3"),Map.of("column","qty","operator","LTE","value","4")));c.put("sorts",List.of(Map.of("column","price","direction","desc")));var r=DataReport.build(table(),c);assertThat(r.sourceRows()).containsExactly(4,3);assertThat(r.rows().get(0)).containsExactly("거래처1","2월","4","30");assertThat(DataReport.rows(table())).hasSize(4);}
 @Test void multipleDimensionsAndMeasuresUseTupleKeysAndAccurateAggregate(){var c=config();c.put("mode","REPORT");c.put("dimensions",List.of("party","month"));c.put("metrics",List.of(Map.of("column","qty","operation","SUM"),Map.of("column","price","operation","AVG"),Map.of("column","","operation","COUNT")));var r=DataReport.build(table(),c);assertThat(r.rows()).containsExactly(List.of("거래처1","1월","5","15","2"),List.of("거래처1","2월","4","30","1"),List.of("거래처2","1월","9","40","1"));}
 @Test void distinctTextDoesNotCountAsInvalidNumeric(){var c=config();c.put("mode","REPORT");c.put("metrics",List.of(Map.of("column","party","operation","DISTINCT")));var r=DataReport.build(table(),c);assertThat(r.rows()).containsExactly(List.of("2"));assertThat(r.excluded()).isZero();}
 @Test void errorsAndProvisionalNumbersAreExcludedPerMeasure(){var t=ExcelCells.mutable(table());ExcelCells.map(ExcelCells.meta(t),"paused").put("C2",Map.of("formula","UNSUPPORTED()","mode","CACHED"));var c=config();c.put("mode","REPORT");c.put("metrics",List.of(Map.of("column","qty","operation","SUM")));var r=DataReport.build(t,c);assertThat(r.rows()).containsExactly(List.of("16"));assertThat(r.excluded()).isEqualTo(1);}
 @Test void selectionsAndBoundariesAreValidated(){var c=config();c.put("columns",List.of("removed"));assertThatThrownBy(()->DataReport.build(table(),c)).isInstanceOf(Problem.class);c.put("columns",List.of("qty","qty"));assertThatThrownBy(()->DataReport.config(c)).isInstanceOf(Problem.class);assertThat(DataReport.number("1e99999999")).isNull();}
 @Test void reportChartsAreSuggestedOnlyWhenShapeMatches(){var c=config();c.put("mode","REPORT");c.put("dimensions",List.of("party"));c.put("metrics",List.of(Map.of("column","qty","operation","SUM")));var r=DataReport.page(DataReport.build(table(),c),0,3);assertThat((List<?>)r.get("charts")).containsAll((Collection)List.of("TABLE","BAR","LINE","PIE"));c.put("metrics",List.of(Map.of("column","qty","operation","SUM"),Map.of("column","price","operation","SUM")));assertThat(((List<?>)DataReport.page(DataReport.build(table(),c),0,3).get("charts")).contains("PIE")).isFalse();}
 @Test void legacyViewsRemainConvertible(){var r=DataReport.build(table(),Map.of("groupColumn","party","operation","SUM","valueColumn","qty","name","기존"));assertThat(r.rows()).containsExactly(List.of("거래처1","9"),List.of("거래처2","9"));}
 @Test void calculatedColumnKeepsSourceAndAddsRealRowFormulas(){var original=WorkbookRules.normalize(table());var book=CalculatedColumn.build(original,Map.of("sheetId","sheet1","label","금액","formula","=C{row}*D{row}","scope","ALL"));var t=WorkbookRules.data(book,"sheet1");assertThat(DataReport.rows(t).get(0)).containsExactly("거래처1","1월","2","10","20");assertThat(ExcelCells.map(ExcelCells.meta(t),"formulas").get("E5")).isEqualTo("C5*D5");assertThat(DataReport.columns(WorkbookRules.data(original,"sheet1"))).hasSize(4);assertThat(CalculatedColumn.preview(book,"sheet1",2,3).get("affectedRows")).isEqualTo(4);}
 @Test void filteredColumnOnlyFillsMatchedRows(){var c=config();c.put("filters",List.of(Map.of("column","party","operator","EQ","value","거래처2")));var book=CalculatedColumn.build(WorkbookRules.normalize(table()),Map.of("sheetId","sheet1","label","금액","formula","=C{row}*D{row}","scope","FILTERED","view",c));var rows=DataReport.rows(WorkbookRules.data(book,"sheet1"));assertThat(rows.get(0).get(4)).isEmpty();assertThat(rows.get(3).get(4)).isEqualTo("360");}
 @Test void lookupAndSumifTemplatesCalculateUsingOriginalSheets(){var source=WorkbookRules.normalize(table());var book=CalculatedColumn.build(source,Map.of("sheetId","sheet1","label","거래처별 수량","formula","=SUMIF($A$2:$A$5,A{row},$C$2:$C$5)","scope","ALL"));assertThat(DataReport.rows(WorkbookRules.data(book,"sheet1")).get(0).get(4)).isEqualTo("9");var lookup=CalculatedColumn.build(source,Map.of("sheetId","sheet1","label","첫 수량","formula","=VLOOKUP(A{row},'시트1'!$A$2:$C$5,3,FALSE)","scope","ALL"));assertThat(DataReport.rows(WorkbookRules.data(lookup,"sheet1")).get(1).get(4)).isEqualTo("2");}
 @Test void globalSearchIncludesHiddenColumnsAndComposesWithAndFilters(){var c=config();c.put("search","거래처1");c.put("columns",List.of("qty"));c.put("filters",List.of(Map.of("column","qty","operator","GTE","value","3")));var result=DataReport.build(table(),c);assertThat(result.rows()).containsExactly(List.of("3"),List.of("4"));assertThat(result.sourceRows()).containsExactly(3,4);c.put("searchColumns",List.of("month"));assertThat(DataReport.build(table(),c).rows()).isEmpty();}
 @Test void searchColumnsAndPageSizeAreValidatedAndOldViewsKeepDefaults(){var old=DataReport.config(config());assertThat(old.get("pageSize")).isEqualTo(100);assertThat(old.get("search")).isEqualTo("");var c=config();c.put("searchColumns",List.of("removed"));assertThatThrownBy(()->DataReport.build(table(),c)).isInstanceOf(Problem.class);c.remove("searchColumns");c.put("pageSize",51);assertThatThrownBy(()->DataReport.config(c)).isInstanceOf(Problem.class);c.put("pageSize",25.5);assertThatThrownBy(()->DataReport.config(c)).isInstanceOf(Problem.class);}
 @Test void paginationUsesChosenSizeAndClampsOutOfRangeWithoutDroppingRows(){var t=ExcelCells.mutable(table());var values=new ArrayList<List<String>>();for(int i=0;i<63;i++)values.add(List.of("업체"+i,"1월",Integer.toString(i),"100"));t.put("rows",values);var c=config();c.put("pageSize",25);var result=DataReport.build(t,c);var page=DataReport.page(result,1,7);assertThat(page.get("pageSize")).isEqualTo(25);assertThat((List<?>)page.get("rows")).hasSize(25);assertThat(((List<?>)page.get("sourceRows")).get(0)).isEqualTo(27);var last=DataReport.page(result,99,7);assertThat(last.get("page")).isEqualTo(2);assertThat((List<?>)last.get("rows")).hasSize(13);}
 @Test void viewPresentationAndDefaultFlagSurviveNormalization(){var c=config();c.put("density","COMPACT");c.put("wrap",true);c.put("defaultView",true);c.put("filterColumns",List.of("party","qty"));var clean=DataReport.config(c);assertThat(clean).containsEntry("density","COMPACT").containsEntry("wrap",true).containsEntry("defaultView",true);assertThat(clean.get("filterColumns")).isEqualTo(List.of("party","qty"));c.put("wrap","true");assertThatThrownBy(()->DataReport.config(c)).isInstanceOf(Problem.class);}
 @Test void numericRangeFiltersDoNotCompareErrorCellsAsText(){var t=ExcelCells.mutable(table());var rows=new ArrayList<List<String>>(DataReport.rows(t));rows.set(0,List.of("거래처1","1월","#REF!","10"));rows.set(1,List.of("거래처1","1월","unknown","20"));t.put("rows",rows);var c=config();c.put("filters",List.of(Map.of("column","qty","operator","GTE","value","1")));assertThat(DataReport.build(t,c).sourceRows()).containsExactly(4,5);}
}
